<template>
  <form class="resource-form" @submit.prevent="$emit('save')">
    <div class="form-title-row"><div><span class="eyebrow">{{ isNew ? 'NEW GAME RESOURCE' : 'EDIT GAME RESOURCE' }}</span><h1>{{ isNew ? '新增游戏' : game.title || '编辑游戏' }}</h1><p>填写常用信息即可，技术 ID 和网址标识会自动维护。</p></div><div class="form-actions"><button type="button" class="button secondary" @click="$emit('cancel')">取消</button><button class="button primary" type="submit">保存游戏</button></div></div>
    <div v-if="errors.length" class="form-errors"><b>保存前请处理以下问题：</b><ul><li v-for="error in errors" :key="error">{{ error }}</li></ul></div>

    <section class="form-section"><header><span class="section-index">01</span><div><h2>基本信息</h2><p>名称、介绍和分类是发布游戏的必要信息。</p></div></header>
      <div class="fields-grid"><label>游戏名称 <em>必填</em><input v-model.trim="game.title" maxlength="100" placeholder="输入游戏名称" /></label><label>游戏副标题<input v-model.trim="game.subtitle" placeholder="一句话介绍游戏" /></label>
        <label class="span-two">游戏介绍 <em>必填</em><textarea v-model.trim="game.description" rows="4" placeholder="介绍玩法、特色和适合的玩家" /></label>
        <div class="span-two"><label>游戏封面</label><div class="cover-edit"><GameCover :src="game.cover" :alt="game.coverAlt" :title="game.title || '封面预览'"/><div class="cover-fields"><label>图片路径或完整 URL<input v-model.trim="game.cover" placeholder="/images/games/example.png 或 https://…" /></label><label>图片替代文本<input v-model.trim="game.coverAlt" placeholder="描述封面内容" /></label><button type="button" class="text-button" @click="clearCover">清空图片路径</button><p class="field-hint">本地图片请先单独放入项目的 public 目录，再填写对应路径。浏览器编辑器不能自动移动电脑上的图片文件，也不会把图片编码进 JSON。</p></div></div></div>
        <div class="span-two"><label>游戏分类 <em>至少选择一项</em></label><div class="check-pills"><label v-for="category in categories" :key="category.id"><input v-model="game.categoryIds" type="checkbox" :value="category.id"/><span>{{ category.name }}</span></label></div></div>
        <ChipField label="标签" :items="game.tags" placeholder="输入标签后按回车" @update:items="game.tags=$event" />
        <ChipField label="游戏平台" :items="game.platforms" placeholder="如 Windows、浏览器" @update:items="game.platforms=$event" />
        <label class="check-inline"><input v-model="game.recommended" type="checkbox"/> 精选推荐</label><label class="check-inline"><input v-model="game.published" type="checkbox"/> 发布到网站</label>
      </div>
    </section>

    <section class="form-section"><header><span class="section-index">02</span><div><h2>下载渠道</h2><p>每个网盘单独管理。未确认授权或演示数据不会显示本站下载按钮。</p></div><button type="button" class="button secondary small-button" @click="addChannel">＋ 添加下载渠道</button></header>
      <div v-if="!game.downloadLinks.length" class="channel-empty"><span>↗</span><b>还没有下载渠道</b><small>可以先保存游戏，确认分发权限后再添加真实链接。</small></div>
      <DownloadChannelCard v-for="(channel,index) in game.downloadLinks" :key="channel.id" :model="channel" :index="index" :providers="providers" :can-publish="channelCanPublish" @remove="removeChannel(index)" />
      <p class="field-hint auth-reminder">{{ channelCanPublish ? '此游戏满足展示本站网盘入口的基本授权条件。只有启用且 URL 有效的渠道会展示。' : '此游戏当前不满足展示本站网盘入口的条件。请勿启用渠道，直到确认授权并将游戏设置为正式发布。' }}</p>
    </section>

    <details class="form-section fold-section"><summary><span class="section-index">03</span><span><b>授权与来源</b><small>确认分发权限后，才能启用本站网盘下载渠道。</small></span></summary><div class="fields-grid"><label>授权状态<select v-model="game.licenseStatus"><option value="pending_review">授权情况待核实</option><option value="official_only">仅提供官方获取链接</option><option value="permission_confirmed">已确认允许本站分发</option></select></label><label class="check-inline"><input v-model="game.demoOnly" type="checkbox"/> 演示数据（永不展示下载入口）</label><label class="span-two">授权说明<textarea v-model.trim="game.licenseNote" rows="2" placeholder="说明授权核实情况" /></label><label>授权证明链接<input v-model.trim="game.licenseUrl" placeholder="https://…" /></label><label>官方获取链接<input v-model.trim="game.sourceUrl" placeholder="https://…" /></label><label class="span-two">资源来源说明<textarea v-model.trim="game.sourceNote" rows="2" placeholder="来源与资源说明" /></label></div></details>

    <details class="form-section fold-section"><summary><span class="section-index">04</span><span><b>高级设置</b><small>网址标识、开发者、版本、特色、操作说明、截图和相关推荐。</small></span></summary><div class="fields-grid"><label>网址标识<input :value="game.slug" @input="game.slug=$event.target.value;$emit('slug-manual')" placeholder="保存时自动生成" /><small class="field-hint">ID 自动维护。您手动修改网址标识后，标题变化不会覆盖它。</small></label><label>开发者<input v-model.trim="game.developer" placeholder="开发者名称" /></label><label>发行年份<input v-model.number="game.releaseYear" type="number" min="1970" max="2100" placeholder="可留空" /></label><label>游戏版本<input v-model.trim="game.version" placeholder="如 1.0.0" /></label><ChipField label="游戏语言" :items="game.language" placeholder="输入语言后按回车" @update:items="game.language=$event"/><label>游戏大小<input v-model.trim="game.gameSize" placeholder="如 850 MB" /></label>
        <ArrayEditor class="span-two" title="游戏特色" :items="game.features" placeholder="添加一项特色" @update:items="game.features=$event"/><ArrayEditor class="span-two" title="操作说明" :items="game.controls" placeholder="添加操作说明" @update:items="game.controls=$event"/><ArrayEditor class="span-two" title="系统要求" :items="game.requirements" placeholder="添加一项系统要求" @update:items="game.requirements=$event"/><ArrayEditor class="span-two" title="游戏截图路径" :items="game.screenshots" placeholder="/images/games/screenshot.png" @update:items="game.screenshots=$event"/><FaqEditor :items="game.faqs" @update:items="game.faqs=$event" />
        <label class="span-two">相关推荐游戏<select v-model="game.relatedGameIds" multiple size="4"><option v-for="item in otherGames" :key="item.id" :value="item.id">{{ item.title }}</option></select><small class="field-hint">按住 Ctrl（Windows）或 Command（Mac）可多选。</small></label>
      </div>
    </details>
    <div class="form-bottom-actions"><button type="button" class="button secondary" @click="$emit('cancel')">取消修改</button><button class="button primary" type="submit">保存游戏资源</button></div>
  </form>
</template>

<script setup>
import { computed, defineComponent, h, ref } from 'vue'
import GameCover from './GameCover.vue'
import DownloadChannelCard from './DownloadChannelCard.vue'
import FaqEditor from './FaqEditor.vue'

const props = defineProps({ game: { type: Object, required: true }, categories: { type: Array, default: () => [] }, allGames: { type: Array, default: () => [] }, providers: { type: Array, default: () => [] }, errors: { type: Array, default: () => [] }, isNew: Boolean })
defineEmits(['save', 'cancel', 'slug-manual'])
const game = props.game
const providers = props.providers
const channelCanPublish = computed(() => game.published && !game.demoOnly && game.licenseStatus === 'permission_confirmed')
const otherGames = computed(() => props.allGames.filter(item => item.id !== game.id))
const split = value => value.split(',').map(item => item.trim()).filter(Boolean)
function clearCover() { game.cover = '' }
function addChannel() { game.downloadLinks.push({ id: `link-${crypto.randomUUID?.() || Date.now()}`, provider: '', label: '', url: '', extractCode: '', version: '', fileSize: '', note: '', enabled: false }) }
function removeChannel(index) { game.downloadLinks.splice(index, 1) }

const ChipField = defineComponent({ props: { label: String, items: { type: Array, default: () => [] }, placeholder: String }, emits: ['update:items'], setup(p,{emit}) { const value=ref(''); function add(){const item=value.value.trim();if(item&&!p.items.includes(item))emit('update:items',[...p.items,item]);value.value=''} return()=>h('div',{class:'chip-field'},[h('label',p.label),h('div',{class:'chip-list'},[...p.items.map((item,index)=>h('span',{class:'chip',key:`${item}-${index}`},[item,h('button',{type:'button','aria-label':`删除${item}`,'onClick':()=>emit('update:items',p.items.filter((_,i)=>i!==index))},'×')])),h('input',{value:value.value,placeholder:p.placeholder,onInput:e=>value.value=e.target.value,onKeydown:e=>{if(e.key==='Enter'||e.key===','){e.preventDefault();add()}}})])])} })
const ArrayEditor = defineComponent({ props:{title:String,items:{type:Array,default:()=>[]},placeholder:String},emits:['update:items'],setup(p,{emit}){const draft=ref('');function add(){const value=draft.value.trim();if(value)emit('update:items',[...p.items,value]);draft.value=''}return()=>h('div',{class:'array-editor'},[h('label',p.title),h('div',{class:'array-list'},p.items.map((item,index)=>h('div',{class:'array-row',key:`${index}-${item}`},[h('span',item),h('button',{type:'button',onClick:()=>emit('update:items',p.items.filter((_,i)=>i!==index))},'删除')]))),h('div',{class:'array-add'},[h('input',{value:draft.value,placeholder:p.placeholder,onInput:e=>draft.value=e.target.value,onKeydown:e=>{if(e.key==='Enter'){e.preventDefault();add()}}}),h('button',{type:'button',onClick:add},'添加')])])} })
</script>

<style scoped>
