:checked+span{border-color:#a6ceff;background:#edf6ff;color:var(--blue)}.check-inline{display:flex!important;align-items:center;gap:7px;min-height:34px}.chip-field>label,.array-editor>label{font-size:12px;color:#526b85;font-weight:700}.chip-list{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:6px;border:1px solid var(--line);border-radius:9px;margin-top:6px;min-height:40px}.chip{display:inline-flex;align-items:center;gap:5px;border-radius:20px;background:#edf5ff;color:#3b73b5;padding:4px 8px;font-size:11px}.chip button{color:#7794b3;font-size:15px;line-height:1}.chip-list input{flex:1;min-width:130px;border:0!important;outline:0;padding:5px!important;margin:0!important}.channel-empty{padding:24px;border:1px dashed #cddceb;border-radius:12px;background:#fbfdff;text-align:center;display:grid;justify-items:center;gap:6px;color:var(--muted)}.channel-empty span{font-size:24px;color:var(--blue)}.channel-empty b{font-size:13px;color:var(--ink)}.channel-empty small{font-size:11px}.auth-reminder{background:#f4f8fd;border-radius:8px;padding:8px 10px}.fold-section{padding:0 20px}.fold-section summary{display:flex;gap:12px;align-items:center;padding:17px 0;cursor:pointer;list-style:none}.fold-section summary::-webkit-details-marker{display:none}.fold-section summary span:last-child{display:grid;gap:4px}.fold-section summary b{font-size:14px}.fold-section summary small{font-size:11px;color:var(--muted)}.fold-section[open] summary{margin-bottom:10px}.fold-section>.fields-grid{padding-bottom:19px}.array-list{display:grid;gap:6px;margin:7px 0}.array-row{display:flex;align-items:center;justify-content:space-between;padding:7px 9px;border:1px solid var(--line);border-radius:8px;color:#5d7289;font-size:12px}.array-row button{color:#cb6366;font-size:11px}.array-add{display:flex;gap:7px}.array-add input{flex:1;min-width:0;padding:8px 10px;border:1px solid var(--line);border-radius:8px;font-size:12px}.array-add button{padding:0 12px;border-radius:8px;background:#eef6ff;color:var(--blue);font-size:11px}.form-errors{padding:12px 15px;border:1px solid #f1c4b8;background:#fff8f5;border-radius:10px;color:#a84d42;font-size:12px}.form-errors ul{margin:6px 0 0;padding-left:18px;line-height:1.7}.form-bottom-actions{display:flex;justify-content:flex-end;gap:9px;padding:8px 0 24px}.small-button{padding:8px 11px;font-size:11px}
@media(max-width:650px){.form-title-row{align-items:flex-start;flex-direction:column}.form-actions{width:100%}.form-actions button{flex:1}.form-section{padding:15px}.fields-grid{grid-template-columns:1fr}.span-two{grid-column:auto}.cover-edit{grid-template-columns:1fr}.cover-edit>.cover-art{height:180px}.form-section>header{align-items:flex-start;flex-wrap:wrap}.form-section>header .small-button{margin-left:46px}}
</style>
